findings.proposedFix:
Keep the `len` calculation and chunk processing unconditional when `chunk !== undefined`, and only guard `this.set('Content-Length', len)` with `!this.get('Transfer-Encoding')`:

```js
  // populate Content-Length
  var len;
  if (chunk !== undefined) {
    if (Buffer.isBuffer(chunk)) {
      // get length of Buffer
      len = chunk.length
    } else if (!generateETag && chunk.length < 1000) {
      // just calculate length when no ETag + small chunk
      len = Buffer.byteLength(chunk, encoding)
    } else {
      // convert chunk to Buffer and calculate
      chunk = Buffer.from(chunk, encoding)
      encoding = undefined;
      len = chunk.length
    }

    if (!this.get('Transfer-Encoding')) {
      this.set('Content-Length', len);
    }
  }
```

suggestedReproduction.reproductionCode:
const assert = require('assert');
const http = require('http');
const express = require('./lib/express');

const app = express();
app.enable('etag');

app.get('/', function(req, res) {
  res.set('Transfer-Encoding', 'chunked');
  res.send('hello world');
});

const server = app.listen(0, function() {
  const port = server.address().port;
  http.get('http://localhost:' + port + '/', function(res) {
    try {
      assert.strictEqual(res.headers['content-length'], undefined, 'Content-Length should not be set');
      assert.ok(res.headers['etag'], 'ETag header should be present even when Transfer-Encoding is set');
      console.log('Test passed');
      server.close();
      process.exit(0);
    } catch (err) {
      console.error('Bug reproduced:', err.message);
      server.close();
      process.exit(1);
    }
  });
});

